 placeDirt(d){const pads=[...stations.map(p=>({...p,r:2.1})),...NEIGHBORS.map(p=>({...p,r:1.7})),...ZONES.map(p=>({x:p.x,z:p.z+5,r:2.1})),{x:0,z:2,r:2.5}],boards=[{x:0,z:-8},...ZONES.map(p=>({x:p.x,z:p.z-3}))];const free=(x,z)=>Math.abs(x)<=45&&z>=-44&&z<=45&&!pads.some(q=>Math.hypot(x-q.x,z-q.z)<q.r+d.size)&&!boards.some(q=>Math.abs(x-q.x)<5.2+d.size&&Math.abs(z-q.z)<2+d.size);if(free(d.x,d.z))return d;for(let i=1;i<=256;i++){let a=i*2.399963,r=.5*Math.sqrt(i),x=d.x+Math.cos(a)*r,z=d.z+Math.sin(a)*r;if(free(x,z)){d.x=x;d.z=z;break;}}return d;}
 addDirt(zone=-2){if(zone===-2){const n=this.rand();zone=n<.35?-1:Math.floor(this.rand()*8);}let center=zone<0?{x:0,z:0}:ZONES[zone];let spread=zone<0?26:19;let x=center.x+(this.rand()-.5)*spread,z=center.z+(this.rand()-.5)*spread;if(zone<0&&Math.abs(x)<3&&Math.abs(z-2)<4)x+=5;this.dirt.push(this.placeDirt({id:++this.id,x,z,hp:9+this.chapter,size:.5+this.rand()*.55,zone}));}
 makeHazards(){let types=['wind','sticky','heal','belt','pulse','fog','nest','pulse'];let type=types[this.chapter];for(let i=0;i<3;i++)this.hazards.push({id:i,x:(i-1)*8,z:-5+(i%2)*6,r:2.5,type,clock:0});for(let i=0;i<ZONES.length;i++){let q=ZONES[i];this.hazards.push({id:10+i,x:q.x-4,z:q.z-1,r:2.5,type:types[i],clock:0});}if(this.mode==='endless'){let arr=['wind','sticky','belt','pulse','nest'];this.hazards.push({id:4,x:0,z:6,r:3,type:arr[this.wave%arr.length],clock:0});}}
 spawn(kind,boss=false,x,z){if(this.enemies.length>=75&&!boss)return;const edge=this.rand()<.5?-1:1;let t=kind||['dust','runner','tank','split','healer','spitter'][Math.floor(this.rand()*Math.min(6,2+this.chapter))];let hp=({dust:19,runner:13,tank:65,split:32,healer:25,spitter:24}[t])*this.scale; if(boss){t='boss';hp=(240+this.chapter*55)*(this.mode==='endless'?1+this.wave*.18:1);}
 this.enemies.push({id:++this.id,kind:t,x:x??edge*(13+this.rand()*2),z:z??(-12+this.rand()*10),hp,maxHP:hp,speed:({dust:1.05,runner:1.7,tank:.57,split:.9,healer:.85,spitter:.8,boss:.47}[t]),clock:0,hit:0,phase:this.rand()*6.28,boss,slow:0});if(boss)this.emit('boss',{name:this.mode==='endless'?'돌아온 먼지 대장':'먼지 대장 · '+this.config.word});}
 clearDirt(d,chain=true){if(d.cleaned)return;d.hp=0;d.cleaned=true;this.totalCleaned++;if(chain){this.combo++;this.comboTime=7;this.bestCombo=Math.max(this.bestCombo,this.combo);if(this.combo===20){this.fever=12;this.emit('fever',{x:this.player.x,z:this.player.z});}}let value=2*(chain?this.comboMultiplier:1);this.drops.push({id:++this.id,x:d.x,z:d.z,value,age:0});this.emit('clean',{x:d.x,z:d.z,value,combo:this.combo});if(chain&&[8,20,40,60,100].includes(this.combo))this.emit('combo',{count:this.combo,multiplier:this.comboMultiplier,x:d.x,z:d.z});}
 giftOffer(n){let s=this.neighborState[n.id]||{count:0,cooldown:0};return {cost:n.cost+Math.min(12,Math.floor(s.count/3)*2),reward:Math.floor((n.reward+Math.floor(s.count/3)*4)*(this.puzzles?.[1]?.solved?1.2:1)),cooldown:s.cooldown};}
 hurt(e,dmg){if(e.hp<=0)return;e.hp-=dmg;e.hit=.13;if(e.hp<=0){this.kills++;this.chapterKills++;this.score+=e.boss?300:10;this.drops.push({id:++this.id,x:e.x,z:e.z,value:e.boss?25:3,age:0});this.emit('pop',{x:e.x,z:e.z,kind:e.kind});if(e.boss){this.bossKilled=true;this.money+=40;this.emit('toast',{text:'먼지 대장 정화! 마을 응원 크레딧 +40'});}if(e.kind==='split'&&this.enemies.length<65){this.spawn('runner',false,e.x-.4,e.z);this.spawn('runner',false,e.x+.4,e.z);}}}
 upgrade(key){const u=UPGRADES.find(v=>v.key===key);if(!u)return false;const cost=this.upgradeCost(key);if(this.money<cost)return false;this.money-=cost;this.levels[key]++;if(key==='repair'){this.baseMax+=30;this.baseHP=this.baseMax;}this.emit('upgrade',{key,cost});return true;}
 upgradeCost(key){let u=UPGRADES.find(v=>v.key===key);return Math.floor(u.base*Math.pow(1.42,this.levels[key]));}
 deliver(n){let state=this.neighborState[n.id]||(this.neighborState[n.id]={cooldown:0,count:0});if(state.cooldown>0)return false;let {cost,reward}=this.giftOffer(n);if(this.supplies+this.carry<cost)return false;let take=Math.min(this.carry,cost);this.carry-=take;this.supplies-=cost-take;this.money+=reward;this.helpCredits+=reward;this.helpCount++;state.count++;state.cooldown=16;this.baseHP=Math.min(this.baseMax,this.baseHP+8);this.emit('gift',{x:n.x,z:n.z,name:n.name,gift:n.gift,reward,cost});return true;}
 interact(s){if(s.type==='depot'){if(this.carry){let n=Math.min(this.carry,3+this.levels.speed);this.supplies+=n;this.carry-=n;this.depotRun+=n;this.emit('deposit',{n,x:s.x,z:s.z,total:this.depotRun,done:this.carry===0});if(!this.carry)this.depotRun=0;}return;}
 if(s.type==='tower'&&this.towers.some(t=>t.id===s.id))return;
 if(s.type==='bot'&&this.bots)return;
 if(s.type==='repair'&&this.baseHP>=this.baseMax-1)return;
 if(this.money<s.cost)return;
 this.money-=s.cost;if(s.type==='tower'){this.towers.push({...s,level:1,cool:0});this.emit('build',{x:s.x,z:s.z,name:s.name,cost:s.cost});}else if(s.type==='bot'){this.bots=1;this.emit('build',{x:s.x,z:s.z,name:s.name,cost:s.cost});}else if(s.type==='repair'){this.baseHP=Math.min(this.baseMax,this.baseHP+65);this.emit('build',{x:s.x,z:s.z,name:'집 내구도 +65'});}}
