 let contactBudget=dt*(22+(this.cityState?.().stage||0)*3),nexusBudget=dt*(12+(this.cityState?.().stage||0)*4);for(let e of this.enemies){if(e.hp<=0)continue;e.hit=Math.max(0,e.hit-dt);e.clock+=dt;let dp=Math.hypot(e.x-p.x,e.z-p.z),tx=dp<4?p.x:0,tz=dp<4?p.z:2;if(e.farmId!=null){let chase=dp<11&&Math.hypot(p.x-e.homeX,p.z-e.homeZ)<18;tx=chase?p.x:e.homeX+Math.sin(e.clock*.35+e.id)*6;tz=chase?p.z:e.homeZ+Math.cos(e.clock*.35+e.id)*6;}let dist=Math.hypot(tx-e.x,tz-e.z);if(dist>.8){e.x+=(tx-e.x)/dist*e.speed*dt*1.2;e.z+=(tz-e.z)/dist*e.speed*dt*1.2;}if(dp<1.4&&p.invul<=0){let damage=Math.min(contactBudget,dt*(e.boss?24:13));contactBudget-=damage;p.hp-=damage;f.damagePlayer+=damage;f.lastHurt=this.totalTime;}if(near(e,0,2,1.65)){let damage=Math.min(nexusBudget,dt*(e.boss?22:9));nexusBudget-=damage;damage=this.filterNexusDamage?.(damage)??damage;this.baseHP-=damage;f.damageBase+=damage;this.damageTaken+=damage;}if(e.kind==='spitter'&&e.clock>3.5&&dp<8&&p.invul<=0){e.clock=0;p.hp-=9;p.invul=Math.max(p.invul,.5);f.damagePlayer+=9;f.lastHurt=this.totalTime;this.emit('spit',{x:e.x,z:e.z,tx:p.x,tz:p.z});}}
 this.enemies=this.enemies.filter(e=>e.hp>0);f.damageClock+=dt;if(f.damageClock>.6){f.damageClock=0;if(f.damagePlayer>=1)this.emit('damage',{x:p.x,z:p.z,n:Math.floor(f.damagePlayer),target:'player'});if(f.damageBase>=1)this.emit('damage',{x:0,z:2,n:Math.floor(f.damageBase),target:'base'});f.damagePlayer=f.damageBase=0;}
 if(this.totalTime-f.lastHurt>12)p.hp=Math.min(100,p.hp+dt*3);
