G.prototype.validateExpansion=function(){if(!['legacy','tycoon','journey'].includes(this.variant))throw Error('모드가 올바르지 않습니다.');if(this.variant==='journey'){const j=this.journey;if(!j||typeof j.listening!=='boolean'||typeof j.ending!=='boolean'||!Number.isFinite(j.hold)||j.hold<0||j.hold>5.1||this.puzzles.some(s=>s.step>3||s.solved!==(s.step===3)))throw Error('이야기 저장이 손상됐습니다.');}if(this.variant==='tycoon'){const f=this.factory;if(f){f.regrowth??=[];f.cleanTiles??={};f.serviceClock??=0;f.openingGrace??=f.served===0&&f.lanes?.every(l=>l.stock===0);if(typeof f.openingGrace!=='boolean')throw Error('첫 주문 기록 오류');if(!Array.isArray(f.regrowth)||f.regrowth.length>1000||!f.cleanTiles||typeof f.cleanTiles!=='object'||Array.isArray(f.cleanTiles)||Object.keys(f.cleanTiles).length>1000||!Number.isFinite(f.serviceClock))throw Error('재생성 저장 오류');for(let d of f.regrowth)if(!Number.isFinite(d.x)||!Number.isFinite(d.z)||Math.abs(d.x)>100||Math.abs(d.z)>100||!Number.isFinite(d.at)||d.at<0||!Number.isFinite(d.size)||d.size<=0||d.size>3||typeof d.key!=='string')throw Error('먼지 재생성 저장 오류');for(let v of Object.values(f.cleanTiles))if(!Number.isFinite(v)||v<0)throw Error('청소 영역 저장 오류');}if(!f||!Array.isArray(f.customers)||f.customers.length>40||!Array.isArray(f.lanes)||f.lanes.length!==4||!Number.isInteger(f.tier)||f.tier<0||f.tier>2)throw Error('공방 저장이 손상됐습니다.');const num=(v)=>Number.isFinite(v)&&v>=0&&v<=1e12;for(let k of ['refineClock','arrival','shiftClock','nextWave','spawnRemaining','enemyClock','transferClock','logisticsClock','vacuumClock','lastHurt','stun','productionPause','damageClock','damagePlayer','damageBase'])if(!Number.isFinite(f[k])||Math.abs(f[k])>1e12)throw Error('공방 시간 기록 오류');if(typeof f.railRide!=='boolean'||!Number.isInteger(f.railSegment)||f.railSegment<0||f.railSegment>=this.railPoints().length)throw Error('레일 저장 오류');for(let k of ['cores','rawBuffer','served','missed','shift','reputation'])if(!num(f[k]))throw Error('공방 자원이 올바르지 않습니다.');for(let k of Object.keys(emptyCargo()))if(!num(f.cargo?.[k])||!num(f.warehouse?.[k]))throw Error('화물 저장 오류');for(let d of SITES){let s=f.sites?.[d.id];if(!s||typeof s.built!=='boolean'||!num(s.paid)||s.paid>d.cost||!Number.isInteger(s.level)||s.level<1||s.level>100||!num(s.output)||!num(s.clock)||!num(s.input?.material)||!num(s.input?.crop))throw Error('기계 저장 오류');}for(let l of f.lanes)if(!num(l.stock)||!num(l.cash))throw Error('판매대 저장 오류');for(let c of f.customers)if(!GOODS[c.kind]||!Number.isInteger(c.lane)||c.lane<0||c.lane>3||!num(c.quantity)||!num(c.filled)||c.filled>c.quantity||!Number.isFinite(c.patience)||!num(c.maxPatience)||!['wait','leave'].includes(c.phase))throw Error('주문 저장 오류');}};
