G.prototype.startJourney=function(){this.variant='journey';this.journey={hold:0,listening:false,note:0,ending:false};this.factory=null;this.mode='story';this.chapter=0;this.money=0;this.supplies=0;this.carry=0;this.puzzles=null;this.ensurePuzzles();this.resetRoom();this.enemies=[];this.towers=[];this.hazards=[];this.dirt=this.dirt.filter(d=>Math.abs(d.x)<15&&Math.abs(d.z)<13);this.events=[];return this;};
const oldSites=G.prototype.puzzleSites,oldNear=G.prototype.puzzleNear,oldProgress=G.prototype.puzzleProgress,oldHint=G.prototype.puzzleHint,oldInteract=G.prototype.puzzleInteract;
G.prototype.puzzleSites=function(){return this.variant==='tycoon'?[]:this.variant==='journey'?[{room:this.chapter,hub:true,x:0,z:-8}]:oldSites.call(this);};
G.prototype.puzzleNear=function(){if(this.variant!=='journey')return oldNear.call(this);let s=this.puzzles[this.chapter];if(s.solved)return null;let best=null;C.JOURNEY_DEFS[this.chapter].nodes.forEach((n,node)=>{let dist=Math.hypot(this.player.x-n.x,this.player.z-(-8+n.z));if(dist<2.3&&(!best||dist<best.dist))best={room:this.chapter,node,x:n.x,z:-8+n.z,dist,label:n.label};});return best;};
G.prototype.puzzleProgress=function(i){return this.variant==='journey'?this.puzzles[i].step:oldProgress.call(this,i);};
G.prototype.puzzleHint=function(i){return this.variant==='journey'?(this.puzzles[i].solved?'마음을 정돈하며 함께 머물러도 좋습니다.':C.JOURNEY_DEFS[i].nodes[this.puzzles[i].step].label):oldHint.call(this,i);};
G.prototype.journeyCommit=function(){let i=this.chapter,s=this.puzzles[i],n=s.step;s.step++;this.journey.listening=false;this.journey.hold=0;if(s.step===3){s.solved=true;this.puzzleWins++;this.emit('journey_solved',{room:i});if(i===6){for(let d of this.dirt){d.hp=0;d.cleaned=true;}this.emit('pulse',{x:0,z:-8});}}this.emit('journey_note',{title:C.JOURNEY_DEFS[i].name,text:NOTES[i][n]});};
G.prototype.puzzleInteract=function(){if(this.variant!=='journey')return oldInteract.call(this);if(this.ready)return false;let near=this.puzzleNear();if(!near)return false;let s=this.puzzles[this.chapter];if(near.node!==s.step){this.emit('toast',{text:C.JOURNEY_DEFS[this.chapter].nodes[s.step].label});return false;}if([2,3,6].includes(this.chapter)&&s.step===2){this.journey.listening=true;this.journey.hold=0;this.emit('toast',{text:'잠시 멈춰 함께 머물러요.'});return true;}this.journeyCommit();return true;};
G.prototype.finishJourneyRoom=function(){if(!this.puzzles[this.chapter].solved||this.ready)return false;this.ready=true;this.emit('complete');return true;};
G.prototype.stepJourney=function(dt,input={x:0,z:0}){if(this.ready)return;dt=Math.min(.1,dt);this.time+=dt;this.totalTime+=dt;let p=this.player,len=Math.hypot(input.x,input.z);if(len>.05){p.x=Math.max(-15,Math.min(15,p.x+input.x/Math.max(1,len)*4.8*dt));p.z=Math.max(-13,Math.min(13,p.z+input.z/Math.max(1,len)*4.8*dt));p.angle=Math.atan2(input.x,input.z);}this.cooldown=Math.max(0,this.cooldown-dt);
 if(this.journey.listening){if(len>.08||Math.hypot(p.x-4,p.z+8)>2.7){this.journey.listening=false;this.journey.hold=0;}else{this.journey.hold+=dt;if(this.journey.hold>=5)this.journeyCommit();}}
 this.cleanClock-=dt;if(this.cleanClock<=0){this.cleanClock=.25;for(let d of this.dirt)if(d.hp>0&&Math.hypot(d.x-p.x,d.z-p.z)<3.2){d.hp-=8;if(d.hp<=0)this.clearDirt(d,false);}}this.dirt=this.dirt.filter(d=>d.hp>0);
 for(let d of this.drops){let dist=Math.hypot(d.x-p.x,d.z-p.z);if(dist<4){d.x+=(p.x-d.x)*dt*5;d.z+=(p.z-d.z)*dt*5;}if(dist<.7){this.carry+=d.value;this.emit('collect',{n:d.value,total:this.carry,x:p.x,z:p.z});d.value=0;}}this.drops=this.drops.filter(d=>d.value>0);
 if(!this.journey.ending&&this.time>=this.duration&&this.puzzles[this.chapter].solved)this.finishJourneyRoom();};
const oldNext=G.prototype.next;G.prototype.next=function(){if(this.variant!=='journey')return oldNext.call(this);if(!this.ready||this.chapter===7)return false;this.chapter++;this.resetRoom();this.enemies=[];this.towers=[];this.hazards=[];this.dirt=this.dirt.filter(d=>Math.abs(d.x)<15&&Math.abs(d.z)<13);this.money=0;this.journey.listening=false;return true;};
const oldSign=G.prototype.signDeed;G.prototype.signDeed=function(){if(this.variant!=='journey')return oldSign.call(this);if(this.chapter!==7||!this.ready)return false;this.journey.ending=true;this.mode='endless';this.ready=false;this.time=0;return true;};
